import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- Constants & Paths ---

const HUMANOID_PATH = "M50 35 C65 35 75 45 80 55 L80 120 L20 120 L20 55 C25 45 35 35 50 35 Z";
const HEAD_CIRCLE = { cx: 50, cy: 20, r: 12 };

// 11 distinct icons (32x32 viewbox normalized to center on chest)
const ICONS = [
  "M16 4L4 9V15C4 22 10 28 16 30C22 28 28 22 28 15V9L16 4Z", // Shield
  "M4 28V12M12 28V4M20 28V16M28 28V8", // Chart
  "M16 4C10 4 6 9 6 14C6 16 7 18 9 19C8 20 7 21 7 23C7 26 10 28 12 28H20C22 28 25 26 25 23C25 21 24 20 23 19C25 18 26 16 26 14C26 9 22 4 16 4Z", // Brain-ish Cloud
  "M18 2L10 14H19L11 30L22 14H14L18 2Z", // Lightning
  "M16 2L4 8V16C4 23 9 28 16 30C23 28 28 23 28 16V8L16 2ZM16 22C14 22 12 20 12 18H20C20 20 18 22 16 22Z", // Security
  "M16 2C8.268 2 2 8.268 2 16S8.268 30 16 30S30 23.732 30 16S23.732 2 16 2ZM16 28C13.8 28 12 22 12 16S13.8 4 16 4S20 10 20 16S18.2 28 16 28ZM4.2 16C4.2 13 5 10 6.5 8M25.5 8C27 10 27.8 13 27.8 16", // Globe
  "M16 4C22 4 28 6 28 9V23C28 26 22 28 16 28C10 28 4 26 4 23V9C4 6 10 4 16 4ZM16 11C10 11 6 13 6 16M26 16C26 13 22 11 16 11", // Database
  "M2 16C2 16 7 6 16 6C25 6 30 16 30 16C30 16 25 26 16 26C7 26 2 16 2 16ZM16 21C18.761 21 21 18.761 21 16C21 13.239 18.761 11 16 11C13.239 11 11 13.239 11 16C11 18.761 13.239 21 16 21Z", // Eye
  "M16 2L20 12L30 12L22 19L25 29L16 23L7 29L10 19L2 12L12 12L16 2Z", // Star
  "M16 28L14.5 26.5C9 21.5 5 18 5 13.5C5 10 8 7 11.5 7C13.5 7 15.5 8 16.5 9.5C17.5 8 19.5 7 21.5 7C25 7 28 10 28 13.5C28 18 24 21.5 18.5 26.5L16 28Z", // Heart
  "M16 16C12 16 8 18 8 22V26H24V22C24 18 20 16 16 16ZM16 4C18.209 4 20 5.791 20 8C20 10.209 18.209 12 16 12C13.791 12 12 10.209 12 8C12 5.791 13.791 4 16 4Z", // User
];

// --- Schema ---



export type NeuralSigmaNetworkProps = Record<string, any>;

const NeuralSigmaNetwork: React.FC<NeuralSigmaNetworkProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 10,
  nodeColor = "#3b82f6", // Blue glow
  lineColor = "#ffffff", // White icons
  gridColor = "rgba(255,255,255,0.05)",
  textColor = "#ffffff",
  pulseSpeed = 1.5,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // --- Background Logic ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Grid background style
  const gridStyle = useMemo(() => {
    if (transparentBackground) return {};
    return {
      backgroundImage: `
        linear-gradient(${gridColor} 1px, transparent 1px),
        linear-gradient(90deg, ${gridColor} 1px, transparent 1px)
      `,
      backgroundSize: "60px 60px",
      backgroundPosition: "center center",
      maskImage: "radial-gradient(circle at center, black 40%, transparent 100%)",
      WebkitMaskImage: "radial-gradient(circle at center, black 40%, transparent 100%)",
    };
  }, [transparentBackground, gridColor]);

  // --- Layout Calculation ---
  const humanoids = useMemo(() => {
    const count = 11;
    const radius = Math.min(width, height) * 0.35;
    const items = [];
    const arcAngle = Math.PI; // 180 degrees semicircle
    const startAngle = Math.PI; // Start from left
    
    // We want them arranged in a semicircle
    for (let i = 0; i < count; i++) {
      // Calculate angle for this item
      // Distribute evenly from PI to 0
      const theta = startAngle - (i / (count - 1)) * arcAngle;
      
      // Parametric circle equation
      const cx = width / 2 + radius * Math.cos(theta);
      const cy = height / 2 + radius * Math.sin(theta) * 0.6 + (height * 0.1); // Flattened oval, shifted down slightly

      items.push({
        id: i,
        x: cx,
        y: cy,
        icon: ICONS[i % ICONS.length],
        delay: i * 5, // frames delay
      });
    }
    return items;
  }, [width, height]);

  // --- Text Animation ---
  const textOpacity = interpolate(
    frame,
    [fps * 2.5, fps * 3.5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const textTranslateY = interpolate(
    frame,
    [fps * 2.5, fps * 3.5],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: (t) => t * (2 - t) }
  );


  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat" }}>
      {/* Grid Background */}
      {!transparentBackground && (
        <AbsoluteFill style={gridStyle} />
      )}

      {/* Main Scene */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
      >
        <defs>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="6" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          
          <linearGradient id="scanline" x1="0%" y1="100%" x2="0%" y2="0%">
             <stop offset="0%" stopColor={nodeColor} stopOpacity="0.1" />
             <stop offset="100%" stopColor={nodeColor} stopOpacity="0.9" />
          </linearGradient>

          {/* Mask for power-on effect */}
           {humanoids.map((h) => {
             // Each humanoid needs its own unique mask based on its delay
             const progress = spring({
               frame: frame - h.delay,
               fps,
               config: { damping: 200, stiffness: 100, mass: 2 },
               durationInFrames: 45
             });
             
             // Map 0-1 to y values
             // The bounding box of the humanoid is roughly 0 to 120 in local coords
             const yVal = interpolate(progress, [0, 1], [130, -10], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

             return (
               <mask id={`mask-${h.id}`} key={`mask-${h.id}`}>
                 <rect x="0" y={yVal} width="100" height="150" fill="white" />
               </mask>
             );
           })}
        </defs>

        {humanoids.map((h, i) => {
            const powerOnProgress = spring({
               frame: frame - h.delay,
               fps,
               config: { damping: 20, stiffness: 80 },
            });
            
            // Icon Pulse
            const pulseStart = fps * 2.5; // Start pulsing after sequence roughly finishes
            const pulseWave = Math.sin((frame - pulseStart) * pulseSpeed + i * 0.5);
            const iconScale = interpolate(pulseWave, [-1, 1], [0.9, 1.1]);
            const iconOpacity = interpolate(powerOnProgress, [0.8, 1], [0, 1], { extrapolateRight: "clamp" });
            const isPulsing = frame > pulseStart;
            
            return (
                <g key={h.id} transform={`translate(${h.x - 50}, ${h.y - 60}) scale(0.8)`}>
                    {/* Dark Silhouette Base */}
                    <path
                        d={HUMANOID_PATH}
                        fill="#111"
                        stroke={nodeColor}
                        strokeWidth="1"
                        strokeOpacity="0.3"
                    />
                    <circle cx={HEAD_CIRCLE.cx} cy={HEAD_CIRCLE.cy} r={HEAD_CIRCLE.r} fill="#111" stroke={nodeColor} strokeWidth="1" strokeOpacity="0.3"/>

                    {/* Lit Version (Masked) */}
                    <g mask={`url(#mask-${h.id})`}>
                         <path
                            d={HUMANOID_PATH}
                            fill="url(#scanline)"
                            filter="url(#glow)"
                        />
                         <circle 
                            cx={HEAD_CIRCLE.cx} 
                            cy={HEAD_CIRCLE.cy} 
                            r={HEAD_CIRCLE.r} 
                            fill={nodeColor}
                            fillOpacity="0.8"
                            filter="url(#glow)"
                        />
                    </g>
                    
                    {/* Chest Icon */}
                    <g 
                        transform={`translate(50, 65) scale(${isPulsing ? iconScale : 1})`} 
                        style={{ transformBox: "fill-box", transformOrigin: "center" }}
                    >
                         {/* Centering the 32x32 icon */}
                         <g transform="translate(-16, -16)">
                            <path
                                d={h.icon}
                                fill={lineColor}
                                fillOpacity={iconOpacity}
                                filter="url(#glow)"
                            />
                         </g>
                    </g>
                </g>
            );
        })}
      </svg>

      {/* Final Text */}
      <div style={{
          position: "absolute",
          bottom: "10%",
          width: "100%",
          textAlign: "center",
          opacity: textOpacity,
          transform: `translateY(${textTranslateY}px)`,
      }}>
          <h1 style={{
              margin: 0,
              fontSize: "3rem",
              fontWeight: 700,
              color: textColor,
              textShadow: `0 0 20px ${nodeColor}`,
              letterSpacing: "4px",
              textTransform: "uppercase"
          }}>
            Your AI Team is Ready
          </h1>
      </div>
    </AbsoluteFill>
  );
};

export default NeuralSigmaNetwork;